using System.Net.Mail;
using System.Security.Claims;
using System.Text.Json;
using System.Text.RegularExpressions;
using Auralis.Api;
using Auralis.Application;
using Auralis.Domain;
using Auralis.Infrastructure;
using Microsoft.EntityFrameworkCore;
public static class Endpoints {
 static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 static Guid U(ClaimsPrincipal u)=>Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);
 static string Encode<T>(T value)=>JsonSerializer.Serialize(value,Json);
 static T Decode<T>(string value)=>JsonSerializer.Deserialize<T>(value,Json)!;
 static object P(Playlist p)=>new{p.Id,p.Name,p.Description,p.Artwork,tracks=p.Tracks.OrderBy(t=>t.Position).Select(t=>Decode<Track>(t.Json)),p.CreatedAt,p.UpdatedAt};
 static object H(PlaybackHistory h)=>new{h.Id,track=Decode<Track>(h.Json),h.Seconds,h.PlayedAt};
 static bool SafeImage(string? s)=>string.IsNullOrEmpty(s)||(s.Length<=2048&&(s.StartsWith("/artwork/")||Uri.TryCreate(s,UriKind.Absolute,out var uri)&&uri.Scheme=="https"));
 static bool ValidTrack(Track t)=>t is not null&&t.Id is {Length:>0 and <=150}&&t.Title is {Length:>0 and <=500}&&t.Artist is {Length:<=500}&&SafeImage(t.Artwork)&&t.Playback is not null && (t.Playback.Kind=="youtube"&&Regex.IsMatch(t.Playback.VideoId??"","^[a-zA-Z0-9_-]{11}$")||t.Playback.Kind=="audio"&&Uri.TryCreate(t.Playback.Url,UriKind.Absolute,out var uri)&&uri.Scheme=="https");
 public static void MapAuralisEndpoints(this WebApplication app) {
 var api=app.MapGroup("/api").RequireRateLimiting("api");
 api.AddEndpointFilter(async (context,next)=>{foreach(var arg in context.Arguments){if(arg is RegisterRequest rr && (rr.Email is null||rr.Password is null||rr.DisplayName is null)||arg is LoginRequest lr&&(lr.Email is null||lr.Password is null)||arg is TokenRequest tr&&tr.RefreshToken is null||arg is PlaylistRequest pr&&pr.Name is null||arg is OrderRequest or&&or.TrackIds is null||arg is HistoryRequest hr&&hr.Track is null||arg is SettingsRequest sr&&(sr.Accent is null||sr.Language is null||sr.Theme is null)||arg is SearchRequest qr&&qr.Query is null||arg is ProfileRequest pf&&pf.DisplayName is null)return Results.BadRequest(new{title="Required fields cannot be null."});}return await next(context);});var auth=api.MapGroup("/auth").RequireRateLimiting("auth");
 auth.MapPost("/register",async(RegisterRequest r,AuralisDb db,AuthService service)=>{var email=r.Email.Trim().ToLowerInvariant();if(!MailAddress.TryCreate(email,out var parsed)||parsed.Address!=email||email.Length>254||r.Password.Length is <10 or >128||string.IsNullOrWhiteSpace(r.DisplayName)||r.DisplayName.Length>80)return Results.ValidationProblem(new Dictionary<string,string[]>{{"account",["Use a valid email, 10–128 character password and 1–80 character name."]}});if(await db.Users.AnyAsync(u=>u.Email==email))return Results.Conflict(new{title="Email is already registered."});var user=new User{Email=email,DisplayName=r.DisplayName.Trim(),PasswordHash=Passwords.Hash(r.Password)};db.Users.Add(user);try{await db.SaveChangesAsync();}catch(DbUpdateException){return Results.Conflict(new{title="Email is already registered."});}return Results.Ok(await service.Issue(user));});
 auth.MapPost("/login",async(LoginRequest r,AuralisDb db,AuthService service)=>{var user=await db.Users.SingleOrDefaultAsync(u=>u.Email==r.Email.Trim().ToLowerInvariant());if(user is null||!Passwords.Verify(r.Password,user.PasswordHash))return Results.Unauthorized();return Results.Ok(await service.Issue(user));});
 auth.MapPost("/refresh",async(TokenRequest r,AuthService service)=>{var result=await service.Refresh(r.RefreshToken);return result is null?Results.Unauthorized():Results.Ok(result);});
 auth.MapPost("/logout",async(TokenRequest r,AuralisDb db)=>{var hash=Passwords.TokenHash(r.RefreshToken);var t=await db.RefreshTokens.SingleOrDefaultAsync(x=>x.Hash==hash);if(t is not null){t.Revoked=true;await db.SaveChangesAsync();}return Results.NoContent();});
 api.MapGet("/auth/me",async(ClaimsPrincipal u,AuralisDb db)=>{var x=await db.Users.FindAsync(U(u));return x is null?Results.Unauthorized():Results.Ok(new UserDto(x.Id,x.Email,x.DisplayName));}).RequireAuthorization();
 api.MapPut("/auth/me",async(ProfileRequest r,ClaimsPrincipal u,AuralisDb db)=>{if(string.IsNullOrWhiteSpace(r.DisplayName)||r.DisplayName.Length>80)return Results.BadRequest();var x=await db.Users.FindAsync(U(u));if(x is null)return Results.Unauthorized();x.DisplayName=r.DisplayName.Trim();await db.SaveChangesAsync();return Results.Ok(new UserDto(x.Id,x.Email,x.DisplayName));}).RequireAuthorization();
 api.MapGet("/music/search",async(string? q,string? type,string? cursor,IMusicProvider provider,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(q)||q.Length>200)return Results.BadRequest(new{title="Search must contain 1–200 characters."});var kind=type??"all";if(!new[]{"all","songs","artists","albums","playlists","videos"}.Contains(kind))return Results.BadRequest();return Results.Ok(await provider.SearchAsync(q,kind,cursor,ct));});
 api.MapGet("/music/home",async(IMusicProvider provider,CancellationToken ct)=>await provider.GetHomeAsync(ct));
 api.MapGet("/music/tracks/{id}",async(string id,IMusicProvider p,CancellationToken ct)=>await p.GetTrackAsync(id,ct) is {} x?Results.Ok(x):Results.NotFound());
 api.MapGet("/music/artists/{id}",async(string id,IMusicProvider p,CancellationToken ct)=>await p.GetArtistAsync(id,ct) is {} x?Results.Ok(x):Results.NotFound());
 api.MapGet("/music/albums/{id}",async(string id,IMusicProvider p,CancellationToken ct)=>await p.GetAlbumAsync(id,ct) is {} x?Results.Ok(x):Results.NotFound());
 api.MapGet("/music/playlists/{id}",async(string id,IMusicProvider p,CancellationToken ct)=>await p.GetPlaylistAsync(id,ct) is {} x?Results.Ok(x):Results.NotFound());
 api.MapGet("/music/recommendations",async(ClaimsPrincipal u,AuralisDb db,IMusicProvider p,CancellationToken ct)=>{var seeds=new List<Track>();if(u.Identity?.IsAuthenticated==true){var id=U(u);var saved=await db.LibraryItems.Where(x=>x.UserId==id&&x.Kind=="favorites").Take(20).ToListAsync(ct);seeds.AddRange(saved.Select(x=>Decode<Track>(x.Json)));var history=await db.History.Where(x=>x.UserId==id).OrderByDescending(x=>x.PlayedAt).Take(20).ToListAsync(ct);seeds.AddRange(history.Select(x=>Decode<Track>(x.Json)));}return await p.GetRecommendationsAsync(seeds,ct);});
 var secured=api.MapGroup("").RequireAuthorization();
 secured.MapGet("/library",async(ClaimsPrincipal u,AuralisDb db)=>{var id=U(u);var items=await db.LibraryItems.Where(x=>x.UserId==id).ToListAsync();return Results.Ok(new{favorites=items.Where(x=>x.Kind=="favorites").Select(x=>Decode<Track>(x.Json)),savedArtists=items.Where(x=>x.Kind=="artists").Select(x=>Decode<ArtistSummary>(x.Json)),savedAlbums=items.Where(x=>x.Kind=="albums").Select(x=>Decode<AlbumSummary>(x.Json)),playlists=(await db.Playlists.Include(x=>x.Tracks).Where(x=>x.UserId==id).ToListAsync()).Select(P),history=(await db.History.Where(x=>x.UserId==id).OrderByDescending(x=>x.PlayedAt).Take(100).ToListAsync()).Select(H)});});
 secured.MapPut("/library/{kind}/{id}",async(string kind,string id,JsonElement body,ClaimsPrincipal u,AuralisDb db)=>{if(!new[]{"favorites","artists","albums"}.Contains(kind)||id.Length>150)return Results.BadRequest();try{if(kind=="favorites"){var t=body.Deserialize<Track>(Json);if(t is null||t.Id!=id||!ValidTrack(t))return Results.BadRequest();}else if(kind=="artists"){var t=body.Deserialize<ArtistSummary>(Json);if(t is null||t.Id!=id||string.IsNullOrWhiteSpace(t.Name)||!SafeImage(t.Artwork))return Results.BadRequest();}else{var t=body.Deserialize<AlbumSummary>(Json);if(t is null||t.Id!=id||string.IsNullOrWhiteSpace(t.Title)||!SafeImage(t.Artwork))return Results.BadRequest();}}catch(JsonException){return Results.BadRequest();}var userId=U(u);var item=await db.LibraryItems.FindAsync(userId,kind,id);if(item is null)db.LibraryItems.Add(new(){UserId=userId,Kind=kind,ItemId=id,Json=body.GetRawText()});else item.Json=body.GetRawText();await db.SaveChangesAsync();return Results.NoContent();});
 secured.MapDelete("/library/{kind}/{id}",async(string kind,string id,ClaimsPrincipal u,AuralisDb db)=>{var x=await db.LibraryItems.FindAsync(U(u),kind,id);if(x is not null){db.Remove(x);await db.SaveChangesAsync();}return Results.NoContent();});
 secured.MapGet("/playlists",async(ClaimsPrincipal u,AuralisDb db)=>(await db.Playlists.Include(p=>p.Tracks).Where(p=>p.UserId==U(u)).ToListAsync()).Select(P));
 secured.MapPost("/playlists",async(PlaylistRequest r,ClaimsPrincipal u,AuralisDb db)=>{if(!ValidPlaylist(r))return Results.BadRequest();var p=new Playlist{UserId=U(u),Name=r.Name.Trim(),Description=r.Description??"",Artwork=r.Artwork??""};db.Add(p);await db.SaveChangesAsync();return Results.Created("/api/playlists/"+p.Id,P(p));});
 secured.MapGet("/playlists/{id:guid}",async(Guid id,ClaimsPrincipal u,AuralisDb db)=>await Owned(id,u,db) is {} p?Results.Ok(P(p)):Results.NotFound());
 secured.MapPut("/playlists/{id:guid}",async(Guid id,PlaylistRequest r,ClaimsPrincipal u,AuralisDb db)=>{if(!ValidPlaylist(r))return Results.BadRequest();var p=await Owned(id,u,db);if(p is null)return Results.NotFound();p.Name=r.Name.Trim();p.Description=r.Description??"";p.Artwork=r.Artwork??"";p.UpdatedAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync();return Results.Ok(P(p));});
 secured.MapDelete("/playlists/{id:guid}",async(Guid id,ClaimsPrincipal u,AuralisDb db)=>{var p=await Owned(id,u,db);if(p is null)return Results.NotFound();db.Remove(p);await db.SaveChangesAsync();return Results.NoContent();});
 secured.MapPost("/playlists/{id:guid}/duplicate",async(Guid id,ClaimsPrincipal u,AuralisDb db)=>{var p=await Owned(id,u,db);if(p is null)return Results.NotFound();var copy=new Playlist{UserId=U(u),Name=p.Name[..Math.Min(90,p.Name.Length)]+" (copy)",Description=p.Description,Artwork=p.Artwork,Tracks=p.Tracks.Select(t=>new PlaylistTrack{TrackId=t.TrackId,Position=t.Position,Json=t.Json}).ToList()};db.Add(copy);await db.SaveChangesAsync();return Results.Ok(P(copy));});
 secured.MapPost("/playlists/{id:guid}/tracks",async(Guid id,Track t,ClaimsPrincipal u,AuralisDb db)=>{if(!ValidTrack(t))return Results.BadRequest();var p=await Owned(id,u,db);if(p is null)return Results.NotFound();if(p.Tracks.Count>=2000)return Results.BadRequest(new{title="Playlist limit is 2000 tracks."});if(p.Tracks.All(x=>x.TrackId!=t.Id)){p.Tracks.Add(new(){TrackId=t.Id,Position=p.Tracks.Count,Json=Encode(t)});p.UpdatedAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync();}return Results.Ok(P(p));});
 secured.MapDelete("/playlists/{id:guid}/tracks/{trackId}",async(Guid id,string trackId,ClaimsPrincipal u,AuralisDb db)=>{var p=await Owned(id,u,db);if(p is null)return Results.NotFound();var t=p.Tracks.FirstOrDefault(x=>x.TrackId==trackId);if(t is not null){p.Tracks.Remove(t);db.Remove(t);var position=0;foreach(var x in p.Tracks.OrderBy(x=>x.Position))x.Position=position++;p.UpdatedAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync();}return Results.Ok(P(p));});
 secured.MapPut("/playlists/{id:guid}/order",async(Guid id,OrderRequest r,ClaimsPrincipal u,AuralisDb db)=>{var p=await Owned(id,u,db);if(p is null)return Results.NotFound();if(!PlaylistOrder.IsValid(p.Tracks.Select(t=>t.TrackId).ToArray(),r.TrackIds))return Results.BadRequest(new{title="Order must be an exact permutation of playlist tracks."});for(var i=0;i<r.TrackIds.Length;i++)p.Tracks.Single(t=>t.TrackId==r.TrackIds[i]).Position=i;p.UpdatedAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync();return Results.Ok(P(p));});
 secured.MapPost("/history",async(HistoryRequest r,ClaimsPrincipal u,AuralisDb db)=>{if(!ValidTrack(r.Track)||r.Seconds is <1 or >300||r.EventId==Guid.Empty)return Results.BadRequest();var id=U(u);if(!await db.History.AnyAsync(h=>h.UserId==id&&h.EventId==r.EventId)){db.History.Add(new(){UserId=id,EventId=r.EventId,TrackId=r.Track.Id,Json=Encode(r.Track),Seconds=r.Seconds});await db.SaveChangesAsync();}return Results.NoContent();});
 secured.MapGet("/history",async(int? skip,int? take,ClaimsPrincipal u,AuralisDb db)=>(await db.History.Where(x=>x.UserId==U(u)).OrderByDescending(x=>x.PlayedAt).Skip(Math.Max(0,skip??0)).Take(Math.Clamp(take??50,1,100)).ToListAsync()).Select(H));
 secured.MapDelete("/history",async(ClaimsPrincipal u,AuralisDb db)=>{var items=await db.History.Where(x=>x.UserId==U(u)).ToListAsync();db.RemoveRange(items);await db.SaveChangesAsync();return Results.NoContent();});
 secured.MapGet("/statistics",async(ClaimsPrincipal u,AuralisDb db)=>{var history=await db.History.Where(x=>x.UserId==U(u)).ToListAsync();var data=history.Select(h=>new{track=Decode<Track>(h.Json),h.Seconds,h.PlayedAt}).ToArray();return Results.Ok(new{totalSeconds=data.Sum(x=>x.Seconds),totalEvents=data.Length,topTracks=data.GroupBy(x=>x.track.Id).Select(g=>new{track=g.First().track,events=g.Count(),seconds=g.Sum(x=>x.Seconds)}).OrderByDescending(x=>x.seconds).Take(10),topArtists=data.GroupBy(x=>x.track.Artist).Select(g=>new{artist=g.Key,events=g.Count(),seconds=g.Sum(x=>x.Seconds)}).OrderByDescending(x=>x.seconds).Take(10),genres=data.GroupBy(x=>x.track.Genre).Select(g=>new{genre=g.Key,seconds=g.Sum(x=>x.Seconds)}),daily=data.GroupBy(x=>x.PlayedAt.UtcDateTime.ToString("yyyy-MM-dd")).Select(g=>new{date=g.Key,seconds=g.Sum(x=>x.Seconds)}).OrderBy(x=>x.date)});});
 secured.MapGet("/settings",async(ClaimsPrincipal u,AuralisDb db)=>{var x=await db.Users.FindAsync(U(u));return x is null?Results.Unauthorized():Results.Ok(new{x.Language,x.Theme,x.Accent});});
 secured.MapPut("/settings",async(SettingsRequest r,ClaimsPrincipal u,AuralisDb db)=>{if(r.Language is not ("pl" or "en")||r.Theme is not ("dark" or "light" or "system")||!Regex.IsMatch(r.Accent,"^#[0-9a-fA-F]{6}$"))return Results.BadRequest();var x=await db.Users.FindAsync(U(u));if(x is null)return Results.Unauthorized();x.Language=r.Language;x.Theme=r.Theme;x.Accent=r.Accent;await db.SaveChangesAsync();return Results.Ok(r);});
 secured.MapGet("/search-history",async(ClaimsPrincipal u,AuralisDb db)=>await db.Searches.Where(x=>x.UserId==U(u)).OrderByDescending(x=>x.SearchedAt).Take(20).Select(x=>x.Query).ToListAsync());
 secured.MapPost("/search-history",async(SearchRequest r,ClaimsPrincipal u,AuralisDb db)=>{if(string.IsNullOrWhiteSpace(r.Query)||r.Query.Length>200)return Results.BadRequest();var id=U(u);var q=r.Query.Trim();var item=await db.Searches.SingleOrDefaultAsync(x=>x.UserId==id&&x.Query==q);if(item is null)db.Searches.Add(new(){UserId=id,Query=q});else item.SearchedAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync();return Results.NoContent();});
 secured.MapDelete("/search-history",async(ClaimsPrincipal u,AuralisDb db)=>{db.RemoveRange(await db.Searches.Where(x=>x.UserId==U(u)).ToListAsync());await db.SaveChangesAsync();return Results.NoContent();});
 }
 static Task<Playlist?> Owned(Guid id,ClaimsPrincipal u,AuralisDb db)=>db.Playlists.Include(p=>p.Tracks).SingleOrDefaultAsync(p=>p.Id==id&&p.UserId==U(u));
 static bool ValidPlaylist(PlaylistRequest r)=>!string.IsNullOrWhiteSpace(r.Name)&&r.Name.Length<=100&&(r.Description?.Length??0)<=1000&&SafeImage(r.Artwork);
}
public record RegisterRequest(string Email,string Password,string DisplayName);
public record LoginRequest(string Email,string Password);
public record TokenRequest(string RefreshToken);
public record ProfileRequest(string DisplayName);
public record PlaylistRequest(string Name,string? Description=null,string? Artwork=null);
public record OrderRequest(string[] TrackIds);
public record HistoryRequest(Track Track,int Seconds,Guid EventId);
public record SettingsRequest(string Language,string Theme,string Accent);
public record SearchRequest(string Query);
